/** The last-check outcome words after "Last checked {time}, " (design-spec 4). */
export function outcomeWords(outcome: AlertOutcome, hits: number): string {
  switch (outcome) {
    case 'nothing-new': return 'nothing new'
    case 'hits': return `${hits} ${hits === 1 ? 'lifer' : 'lifers'}`
    case 'unreachable': return 'offline'
    case 'no-answer': return 'eBird did not answer'
    case 'busy': return 'eBird busy'
    case 'key-rejected': return 'eBird did not accept your key'
  }
}

