/** The card row's second line: "6 alerts, 3 new", "1 alert", "No alerts yet". */
export function inboxRowSub(n: number, newCount: number): string {
  if (n === 0) return INBOX_NONE_YET
  return `${inboxCount(n)}${newCount > 0 ? `, ${newCount} new` : ''}`
}

/** The card row's accessible name: "Inbox, 6 alerts, 3 new", "Inbox, no alerts yet". */
export function inboxRowName(n: number, newCount: number): string {
  if (n === 0) return `${INBOX_LABEL}, no alerts yet`
  return `${INBOX_LABEL}, ${inboxRowSub(n, newCount)}`
}

// ── Times ─────────────────────────────────────────────────────────────────────

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'] as const

/** A minute of the local day as the design writes it: "10:00 PM", "7:00 AM". */
export function clockFromMinutes(min: number): string {
  const h24 = Math.floor(min / 60) % 24
  const m = min % 60
  const h = h24 % 12 === 0 ? 12 : h24 % 12
  return `${h}:${String(m).padStart(2, '0')} ${h24 < 12 ? 'AM' : 'PM'}`
}

/** An instant's local time: "9:41 AM" (a plain space, never U+202F). */
export function clockAt(ms: number): string {
  const d = new Date(ms)
  return clockFromMinutes(d.getHours() * 60 + d.getMinutes())
}

function sameLocalDay(a: Date, b: Date): boolean {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate()
}

/**
 * When something happened, relative to `nowMs`, in local time: the time alone
 * today ("9:41 AM"), "Yesterday, 4:10 PM", else the app's date format without
 * the year and the time ("Sep 27, 11:03 AM"). Used for the alerted time and
 * the status line's check time.
 */
export function whenLocal(ms: number, nowMs: number, pref: DateFormatPref = getDateFormatPref()): string {
  const at = new Date(ms)
  const now = new Date(nowMs)
  const t = clockAt(ms)
  if (sameLocalDay(at, now)) return t
  const y = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1)
  if (sameLocalDay(at, y)) return `Yesterday, ${t}`
  const mo = MONTHS[at.getMonth()]!
  const day = at.getDate()
  const date = pref === 'iso'
    ? `${at.getFullYear()}-${String(at.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`
    : pref === 'day-first' ? `${day} ${mo}` : `${mo} ${day}`
  return `${date}, ${t}`
}

/** The status line's lead sentence for a last check. */
export function lastCheckedSentence(check: LastCheck, nowMs: number, pref?: DateFormatPref): string {
  const at = Date.parse(check.completedAt)
  const when = Number.isFinite(at) ? whenLocal(at, nowMs, pref) : ''
  return `Last checked ${when}, ${outcomeWords(check.outcome, check.hits)}`
}

/** The quiet-hours note under the two times (design-spec section 3). */
export function quietNote(startMin: number, endMin: number): string {
  if (startMin === endMin) return QUIET_EQUAL
  const start = clockFromMinutes(startMin)
  const end = clockFromMinutes(endMin)
  const across = endMin < startMin ? ', across midnight' : ''
  return `Quiet from ${start} to ${end}${across}. A find inside the window is delivered at ${end}.`
}

/** The device's IANA zone (the widget twin's civil-day arithmetic needs one). */
export function deviceZone(): string {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || 'UTC'
  } catch {
    return 'UTC'
  }
}

/** "today", "yesterday", "3 days ago" (the widget twin's calendar days,
 *  lowercase inside the sentence); a future-dated report reads "today". */
export function reportedDayWord(obsDt: string, nowMs: number, tz: string = deviceZone()): string {
  const d = parseObsDateStrict(obsDt)
  if (!d) return 'on an unknown day'
  const days = daysBetween(d, localCivilDate(nowMs, tz))
  if (days <= 0) return 'today'
  if (days === 1) return 'yesterday'
  return `${days} days ago`
}

export function placeLabel(p: PlacePhrase): string {
  return p.kind === 'name' ? p.name : p.kind === 'near-you' ? 'Near you' : 'Nearby'
}

/** A row's visible third line: "Reported today · Alerted 9:41 AM". */
export function rowWhen(row: InboxRow, nowMs: number, tz?: string, pref?: DateFormatPref): { day: string; alerted: string } {
  const at = Date.parse(row.alertedAt)
  return {
    day: reportedDayWord(row.obsDt, nowMs, tz),
    alerted: Number.isFinite(at) ? whenLocal(at, nowMs, pref) : '',
  }
}

/** A row's accessible name, one sentence (design-spec section 7), prefixed
 *  "New. " for a row alerted after the inbox was last viewed (7.3). */
export function rowLabel(row: InboxRow, nowMs: number, tz?: string, pref?: DateFormatPref, isNew = false): string {
  const w = rowWhen(row, nowMs, tz, pref)
  const place = row.locName || placeLabel(row.place)
  return `${isNew ? NEW_PREFIX : ''}${row.comName}, ${place}, ${row.distanceMi.toFixed(1)} miles, reported ${w.day}, alerted ${w.alerted}. Show on the map`
}
